      "newText": "using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json;

namespace AiBox.DevPortal.Services;

public class ModelBenchmarkResultService
{
    private readonly string _resultsPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "tools", "model-benchmark", "results");

    public List<BenchmarkResultSummary> LoadResultSummaries()
    {
        var summaries = new List<BenchmarkResultSummary>();
        var files = Directory.GetFiles(_resultsPath, "*.json");

        foreach (var file in files)
        {
            var content = File.ReadAllText(file);
            var result = JsonConvert.DeserializeObject<BenchmarkResult>(content);
            summaries.Add(new BenchmarkResultSummary
            {
                FileName = Path.GetFileName(file),
                AverageTime = result.AverageTime,
                MinTime = result.MinTime,
                MaxTime = result.MaxTime
            });
        }

        return summaries;
    }
}

public class BenchmarkResult
{
    public double AverageTime { get; set; }
    public double MinTime { get; set; }
    public double MaxTime { get; set; }
}

public class BenchmarkResultSummary
{
    public string FileName { get; set; }
    public double AverageTime { get; set; }
    public double MinTime { get; set; }
    public double MaxTime { get; set; }
}
",
